import{_ as e,o as l,c as a,a0 as i}from"./chunks/framework.DQOulFGV.js";const d="data:image/svg+xml;base64,",c=JSON.parse('{"title":"第1章 线程模型","description":"","frontmatter":{},"headers":[],"relativePath":"redis/02-standalone-core/chapter-01-thread-model.md","filePath":"redis/02-standalone-core/chapter-01-thread-model.md"}'),s={name:"redis/02-standalone-core/chapter-01-thread-model.md"};function I(n,t,o,p,g,h){return l(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="第1章-线程模型" tabindex="-1">第1章 线程模型 <a class="header-anchor" href="#第1章-线程模型" aria-label="Permalink to &quot;第1章 线程模型&quot;">​</a></h1><blockquote><p>Redis 为什么快，最常被提到的答案是「单线程」。但这个说法只对了一半——命令执行是单线程，网络 IO 在 6.0 之后却可以多线程。本章拆解 Redis 的线程模型与 IO 多路复用机制，把「为什么快」讲清楚。</p></blockquote><hr><h2 id="_1-1-单线程模型" tabindex="-1">1.1 单线程模型 <a class="header-anchor" href="#_1-1-单线程模型" aria-label="Permalink to &quot;1.1 单线程模型&quot;">​</a></h2><p>Redis 的核心是单线程执行命令：同一时刻只有一个命令在执行，命令之间天然串行，不存在线程切换、锁竞争、上下文切换的开销。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端 A ──┐</span></span>
<span class="line"><span>客户端 B ──┤──► 事件循环（单线程）──► 逐个执行命令</span></span>
<span class="line"><span>客户端 C ──┘</span></span></code></pre></div><p><strong>单线程为什么反而快</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">因素</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">纯内存操作</td><td style="text-align:left;">数据都在内存，瓶颈不在 CPU，而在内存与网络</td></tr><tr><td style="text-align:left;">无锁无切换</td><td style="text-align:left;">单线程避免线程切换与锁竞争，CPU 不空转</td></tr><tr><td style="text-align:left;">IO 多路复用</td><td style="text-align:left;">一个线程通过 epoll 同时监听成千上万个连接</td></tr><tr><td style="text-align:left;">高效数据结构</td><td style="text-align:left;">SDS、跳表、字典等，多数操作 O(1)/O(log n)</td></tr></tbody></table><p><strong>单线程的边界</strong>：单线程意味着<strong>慢命令会阻塞所有其他请求</strong>。一个耗时 1 秒的命令，会让整个 Redis 停顿 1 秒。所以 Redis 的优化核心是「避免慢命令」（见第 2 章与第五卷）。</p><blockquote><p>辅助线程：虽然命令执行是单线程，但 Redis 有多个后台线程处理耗时操作——AOF 刷盘、UNLINK 异步删除大 Key、Lazy Free 惰性释放，这些不阻塞命令执行。</p></blockquote><hr><h2 id="_1-2-io-多路复用" tabindex="-1">1.2 IO 多路复用 <a class="header-anchor" href="#_1-2-io-多路复用" aria-label="Permalink to &quot;1.2 IO 多路复用&quot;">​</a></h2><p>IO 多路复用让一个线程同时监听多个网络连接。它的演进是从「轮询」到「事件通知」。</p><h3 id="select-poll-的局限" tabindex="-1">select / poll 的局限 <a class="header-anchor" href="#select-poll-的局限" aria-label="Permalink to &quot;select / poll 的局限&quot;">​</a></h3><p>早期的 <code>select</code> 和 <code>poll</code> 每次调用都要把监听的所有文件描述符（fd）从用户态拷贝到内核态，内核再遍历全部 fd 找出就绪的，时间复杂度 O(n)。连接数一多，性能急剧下降。</p><h3 id="epoll-的改进" tabindex="-1">epoll 的改进 <a class="header-anchor" href="#epoll-的改进" aria-label="Permalink to &quot;epoll 的改进&quot;">​</a></h3><p>Linux 的 <code>epoll</code> 采用「注册 + 事件通知」模型：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>epoll_create  创建 epoll 实例</span></span>
<span class="line"><span>epoll_ctl     注册需要监听的 fd（一次注册，长期有效）</span></span>
<span class="line"><span>epoll_wait    阻塞等待就绪事件（内核直接返回就绪 fd 列表）</span></span></code></pre></div><p>核心改进：</p><table tabindex="0"><thead><tr><th style="text-align:left;">能力</th><th style="text-align:left;">select/poll</th><th style="text-align:left;">epoll</th></tr></thead><tbody><tr><td style="text-align:left;">获取就绪 fd</td><td style="text-align:left;">每次遍历全部 fd，O(n)</td><td style="text-align:left;">内核维护就绪列表，直接返回</td></tr><tr><td style="text-align:left;">用户态拷贝</td><td style="text-align:left;">每次拷贝全部 fd</td><td style="text-align:left;">只需处理就绪的 fd</td></tr><tr><td style="text-align:left;">连接数上限</td><td style="text-align:left;">select 固定 1024，poll 无上限但慢</td><td style="text-align:left;">无硬性上限，性能稳定</td></tr></tbody></table><p>Redis 使用 <code>epoll</code>（Linux）/ <code>kqueue</code>（macOS）/ <code>evport</code>（Solaris）等平台最优的多路复用实现，封装在统一的事件循环里。</p><hr><h2 id="_1-3-reactor-模式" tabindex="-1">1.3 Reactor 模式 <a class="header-anchor" href="#_1-3-reactor-模式" aria-label="Permalink to &quot;1.3 Reactor 模式&quot;">​</a></h2><p>Redis 的事件处理采用 Reactor 模式——一个事件分发器 + 多个事件处理器。</p><p><img src="`+d+`" alt="Redis Reactor 事件循环模型"></p><p>事件循环的工作流程：</p><ol><li><code>epoll_wait</code> 阻塞等待就绪事件</li><li>根据事件类型（可读 / 可写）分发到对应处理器</li><li>可读事件 → 读取请求、解析命令、执行、准备响应</li><li>可写事件 → 把响应写回客户端</li></ol><p>三类事件：</p><table tabindex="0"><thead><tr><th style="text-align:left;">事件</th><th style="text-align:left;">触发时机</th><th style="text-align:left;">处理</th></tr></thead><tbody><tr><td style="text-align:left;">连接事件</td><td style="text-align:left;">新客户端建立连接</td><td style="text-align:left;">接受连接、初始化客户端</td></tr><tr><td style="text-align:left;">读事件</td><td style="text-align:left;">客户端发来命令</td><td style="text-align:left;">读取并解析命令</td></tr><tr><td style="text-align:left;">写事件</td><td style="text-align:left;">响应可写回</td><td style="text-align:left;">把结果写回客户端</td></tr></tbody></table><hr><h2 id="_1-4-6-0-的多线程网络-io" tabindex="-1">1.4 6.0 的多线程网络 IO <a class="header-anchor" href="#_1-4-6-0-的多线程网络-io" aria-label="Permalink to &quot;1.4 6.0 的多线程网络 IO&quot;">​</a></h2><p>Redis 6.0 引入了多线程网络 IO，但<strong>命令执行仍然是单线程</strong>。</p><h3 id="瓶颈在哪" tabindex="-1">瓶颈在哪 <a class="header-anchor" href="#瓶颈在哪" aria-label="Permalink to &quot;瓶颈在哪&quot;">​</a></h3><p>单线程模型下，网络 IO 的读写（<code>read</code>/<code>write</code>）本身也是 CPU 密集操作。当连接数多、吞吐量大时，解析协议、写回响应会占满单核 CPU，成为瓶颈。</p><h3 id="_6-0-的改进" tabindex="-1">6.0 的改进 <a class="header-anchor" href="#_6-0-的改进" aria-label="Permalink to &quot;6.0 的改进&quot;">​</a></h3><p>6.0 起，Redis 把「读请求解析」和「写响应」这两步交给多个 IO 线程并行处理，而命令的真正执行仍在主线程串行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>主线程：读事件分发 → 多线程解析请求 → 主线程执行命令 → 多线程写回响应</span></span>
<span class="line"><span>              │              ▲                  │                ▲</span></span>
<span class="line"><span>              └── IO线程1 ────┘                  └─── IO线程1 ────┘</span></span>
<span class="line"><span>              └── IO线程2 ────┘                  └─── IO线程2 ────┘</span></span></code></pre></div><p>关键点：</p><table tabindex="0"><thead><tr><th style="text-align:left;">环节</th><th style="text-align:left;">线程</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;">协议解析</td><td style="text-align:left;">多线程</td><td style="text-align:left;">把网络字节流解析成命令</td></tr><tr><td style="text-align:left;">命令执行</td><td style="text-align:left;">单线程</td><td style="text-align:left;">保证原子性，无锁</td></tr><tr><td style="text-align:left;">响应写回</td><td style="text-align:left;">多线程</td><td style="text-align:left;">把结果写回客户端</td></tr></tbody></table><h3 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">io-threads</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 4</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                  # IO 线程数（默认 1 = 关闭多线程）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">io-threads-do-reads</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yes</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 是否开启多线程读</span></span></code></pre></div><blockquote><p>只有当 CPU 核数较多（≥ 4 核）且确实存在网络 IO 瓶颈时才建议开启多线程 IO。核数少或瓶颈在命令执行时，开启多线程反而可能因线程切换降低性能。</p></blockquote>`,42)])])}const m=e(s,[["render",I]]);export{c as __pageData,m as default};
